<section class="admin-page-head"><div><p class="admin-kicker">M11 · LEGALES</p><h1>Documentos legales versionados</h1><p>Cada guardado crea una versión inmutable. Usa únicamente textos aprobados por el negocio.</p></div><a class="admin-secondary-button" href="/admin/cms">Contenido</a></section>
<?php if($error):?><p class="admin-alert admin-alert-error" role="alert"><?= e($error) ?></p><?php endif?><form class="admin-panel admin-form" method="post" action="/admin/cms/legal"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="operation_key" value="<?= e(($values['operation_key']??'')?:bin2hex(random_bytes(24))) ?>"><div class="admin-form-grid"><label class="admin-field"><span>Documento</span><select name="code"><option value="privacy" <?= ($values['code']??'privacy')==='privacy'?'selected':'' ?>>Aviso de privacidad</option><option value="quote_conditions" <?= ($values['code']??'')==='quote_conditions'?'selected':'' ?>>Condiciones de cotización</option></select></label><label class="admin-field"><span>Título</span><input name="title" maxlength="180" value="<?= e($values['title']??'') ?>" required></label></div><label class="admin-field"><span>Texto aprobado (sin HTML)</span><textarea name="body" rows="12" maxlength="40000" required><?= e($values['body']??'') ?></textarea></label><label class="admin-check"><input type="checkbox" name="publish" value="1" <?= ($values['publish']??'')==='1'?'checked':'' ?>> Publicar esta nueva versión</label><button class="admin-primary-button">Crear versión</button></form>
<section class="admin-panel"><h2>Versiones registradas</h2><?php foreach(array_slice($versions,0,25) as $v):?><details><summary><?= e($v['code']) ?> · Versión <?= e($v['version_number']) ?> · <?= $v['published_at']?'Publicada':'Borrador inmutable' ?></summary><h3><?= e($v['title']) ?></h3><p class="cms-prose"><?= e($v['body']) ?></p><p>SHA-256: <span class="cms-break"><?= e($v['content_hash']) ?></span></p><p><?= e($v['created_at']) ?> UTC</p><?php if($v['published_at']):?><a href="/legal?document=<?= e($v['code']) ?>&amp;version=<?= e($v['id']) ?>">Consultar versión pública</a><?php endif?></details><?php endforeach?><?php if(!$versions):?><p>No hay documentos legales. La recepción pública permanece cerrada sin aviso publicado.</p><?php endif?><nav class="cms-tabs" aria-label="Paginación"><?php if($offset):?><a href="/admin/cms/legal?offset=<?= e(max(0,$offset-25)) ?>">Anterior</a><?php endif?><?php if(count($versions)>25):?><a href="/admin/cms/legal?offset=<?= e($offset+25) ?>">Siguiente</a><?php endif?></nav></section>
